INSERT INTO public.products (id, category_id, name, slug, sku, short_description, description, price, compare_at_price, active, featured, stock_quantity, low_stock_threshold, created_at, updated_at, specifications, highlights, application_steps) VALUES ('10f60bde-edc7-48fe-942c-df66a52a7982', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Quick Wax', 'quick-wax', 'quick-wax', 'An easy‑on, easy‑off liquid wax that leaves a brilliant shine in minutes. Ideal for maintenance.', null, '90.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:06.651337+00', '{"Scent": "Sweet Coconut", "Wax Type": "Liquid Carnauba & Reactive Silicone Polymers", "Cure Time": "Instant (No Haze Wait Required)", "Durability": "Up to 8 Weeks", "Gloss Index": "98/100 Deep Reflective Shine"}', '["Lightning-Fast Wipe-On, Wipe-Off Application", "Produces Deep, Warm Carnauba Glow on Dark Paints", "Leaves Super Hydrophobic Water-Repelling Finish", "Non-Staining on Black Rubber Trims & Badges"]', '[{"title": "Wash Vehicle", "instruction": "Ensure vehicle is completely clean and dry before wax application."}, {"title": "Mist Section", "instruction": "Spray 2-3 mists per half-panel on hood, doors, and fenders."}, {"title": "Spread Evenly", "instruction": "Spread with a soft microfiber towel to create an even, transparent film."}, {"title": "Immediate Buff", "instruction": "No need to wait for haze — buff immediately with a dry microfiber cloth to high gloss."}]'), ('150de4be-5eab-4f4e-926b-f82a9586878c', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Detail Prep Shampoo', 'detail-prep-shampoo', 'detail-prep-shampoo', 'pH neutral pre‑wash shampoo that gently lifts dirt and prepares paint for correction.', null, '50.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:50.86134+00', '{"Dilution": "50ml per 10 Litres Water (1:200)", "pH Level": "7.0 Pure Neutral", "Lubricity": "High-Slip Anti-Mar Polymers", "Foam Profile": "Dense Clinging Suds", "Wax Strip Safe": "Preserves Existing Waxes & Sealants"}', '["Gentle pH-Neutral Daily Maintenance Wash", "Encapsulates Dirt Particles to Prevent Swirl Marks", "Leaves No Water Spots or Film Residue", "Safe on Ceramic Coatings, Sealants & Matte Finishes"]', '[{"title": "Pre-Rinse", "instruction": "Blast vehicle with high-pressure water to knock off heavy grit and dirt."}, {"title": "Prepare Wash Buckets", "instruction": "Add 50ml of Detail Prep Shampoo into a 10L bucket and froth with a water jet."}, {"title": "Two-Bucket Wash", "instruction": "Wash panel by panel from top to bottom, rinsing your wash mitt frequently."}, {"title": "Sheet Rinse & Dry", "instruction": "Rinse thoroughly with an open hose flow and dry with a plush microfibre drying towel."}]'), ('254b21cf-cd0c-40a6-aac1-99066d6352cb', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Whitewall Blast', 'whitewall-blast', 'whitewall-blast', 'Specially formulated to clean whitewall tyres. Removes browning and stains instantly.', null, '80.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:29.62038+00', '{"Target": "Whitewall Tyres, White Lettering, Raised Tyre Text", "Rinsing": "Free-Rinsing Formula", "pH Level": "High Alkaline 12.0", "Action Time": "60 Seconds Rapid Whitening", "Active Chemistry": "Bleaching & Heavy Degreasing Surfactants"}', '["Instantly Restores Dingy, Yellowed Whitewalls to Brilliant White", "Removes Embedded Road Tar, Brake Dust & Kerb Scuffs", "Formulated Specifically for Classic Cars, Hot Rods & Cruiser Tyres", "Safe for White Lettering on Off-Road & All-Terrain Tyres"]', '[{"title": "Wet Tyre", "instruction": "Wet the tyre surface with clean water."}, {"title": "Spray Whitewall Area", "instruction": "Spray Whitewall Blast directly onto the white rubber band or lettering."}, {"title": "Scrub with Stiff Brush", "instruction": "Scrub briskly with a firm nylon tyre brush for 30-60 seconds."}, {"title": "Rinse Clean", "instruction": "Rinse thoroughly with clean water to reveal glowing, factory-bright white rubber."}]'), ('2fd22bd8-f21d-491a-8ed7-161f4adf9ada', '933d2b3c-962e-41ad-bf18-912fe2fe6761', 'Microfibre Cloth', 'microfibre-cloth', 'microfibre-cloth', 'Lint free, ultra soft microfibre cloth for scratch free cleaning and buffing.', null, '25.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:55.431509+00', '{"GSM": "400 GSM Plush Dual-Pile", "Blend": "80/20 Polyester/Polyamide Premium Weave", "Lint Free": "100% Guaranteed Non-Shedding", "Dimensions": "40cm x 40cm Edgeless Laser-Cut", "Wash Cycles": "500+ Machine Washes"}', '["Scratch-Free Edgeless Ultrasonic Border", "Short Pile for Wax/Coating Removal, Long Pile for Buffing", "Traps Micro-Dust Deep within Fibers", "Ideal for Quick Detailers, Glass, Interior & Wax Buffing"]', '[{"title": "Fold in Four", "instruction": "Fold towel twice into a square to provide 8 fresh, clean wiping faces."}, {"title": "Linear Strokes", "instruction": "Wipe in straight, overlapping lines rather than circular motions to prevent marring."}, {"title": "Flip to Clean Face", "instruction": "Flip to a fresh quarter as soon as dirt or residue begins loading on the towel."}, {"title": "Washing Care", "instruction": "Machine wash with dedicated microfiber detergent; do not use fabric softeners."}]'), ('36fcbd7c-bb75-4a76-9abb-6ed716273fc2', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Tyre Trim', 'tyre-trim', 'tyre-trim', 'This tyre & trim restores a deep, rich black finish while shielding against UV rays and weather. Non-greasy, long‑lasting, and simple to apply.', null, '80.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:10.017759+00', '{"Finish": "Deep Rich Satin-Black OEM Finish", "Durability": "Up to 30 Days", "Formulation": "Multi-Surface Polymer Restorer", "UV Protection": "Integrated Anti-Oxidant UV Absorbers", "Target Surfaces": "Tyres, Exterior Plastic Trim, Rubbers, Bumpers"}', '["Dual-Purpose Dressing for Both Tyres & Faded Black Trim", "Brings Sun-Faded Grey Plastics Back to Showroom Black", "Non-Greasy Touch-Dry Finish Will Not Attract Dirt", "Weather-Resistant Barrier Survives Multiple Rain Showers"]', '[{"title": "Clean Surface", "instruction": "Clean tyres and trim thoroughly with Degreaser or APC and let dry completely."}, {"title": "Apply Dressing", "instruction": "Dispense a small amount onto a foam applicator or microfiber pad."}, {"title": "Work Into Texture", "instruction": "Work into textured plastic moldings or tyre rubber using moderate pressure."}, {"title": "Buff Excess", "instruction": "After 5 minutes, wipe over with a dry microfiber cloth to remove any excess film."}]'), ('398c2e9d-b817-4bad-9767-7e0de51753ee', 'da1c2345-2c3f-48a3-bba8-5c31a55178c7', 'Dash Flash', 'dash-flash', 'dash-flash', 'An interior dressing that leaves dashboards and trim with a natural finish.', null, '65.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:37.004307+00', '{"Scent": "Signature New Car Aroma", "Finish": "OEM Matte / Satin (Non-Greasy)", "Anti-Static": "Advanced Dust Repellent Technology", "Surface Safe": "Vinyl, Plastic, Rubber, Sealed Leather", "UV Protection": "SPF 50+ Broad Spectrum UV Blockers"}', '["Factory Original Non-Sticky Satin Finish", "Prevents Dashboard Fading & Heat Cracking", "Anti-Static Repels Dust for Weeks", "Eliminates Dangerous Windshield Glare"]', '[{"title": "Pre-Clean", "instruction": "Remove loose grime with Interior Cleaner and allow surfaces to dry."}, {"title": "Apply to Applicator", "instruction": "Spray 2-3 pumps onto a microfiber applicator pad rather than directly on electronics."}, {"title": "Spread Evenly", "instruction": "Wipe smoothly across dashboard, door cards, and interior trim."}, {"title": "Level Off", "instruction": "Wait 60 seconds and buff lightly with a dry microfiber cloth to lock in the matte OEM look."}]'), ('3a3394b1-5ef1-4aef-a7a7-4e15ada864b2', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Ceramic Force', 'ceramic-force', 'ceramic-force', 'Advanced ceramic spray coating that bonds to paint, providing months of hydrophobic protection and gloss.', 'Ceramic Force is an ultra-hydrophobic SiO2 ceramic spray coating engineered to deliver unmatched gloss, slickness, and lasting protection. Forming a cross-linked covalent bond with clear coat, it repels water, road grime, UV radiation, and environmental contaminants for up to 6 months. Ideal as a standalone protectant or as a booster for professional ceramic coatings.', '80.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:33.862114+00', '{"Technology": "Cross-Linked SiO2 Ceramic Resin", "Durability": "Up to 6 Months", "Cure Time": "2 Hours (Full Cure 24 Hours)", "Water Contact Angle": "110\u00b0 Extreme Hydrophobic Beading", "Safe Surfaces": "Clear Coat, Glass, Wheels, Chrome, Gelcoat"}', '["Creates Extreme Hydrophobic Self-Cleaning Water Beading", "Infused with High-Grade SiO2 Polymers for Glass-Like Reflections", "Shields Clear Coat Against Harsh UV Rays, Acid Rain & Industrial Fallout", "Effortless Spray-On, Wipe-Off Application with Zero Streaking"]', '[{"title": "Decontaminate Surface", "instruction": "Ensure vehicle paintwork is thoroughly washed, clayed, and wiped with an IPA prep spray."}, {"title": "Apply Light Mist", "instruction": "Lightly mist 2-3 sprays of Ceramic Force onto a microfiber applicator pad or folded microfiber towel."}, {"title": "Spread in Crosshatch", "instruction": "Evenly spread over a 2x2 ft section using overlapping crosshatch motions."}, {"title": "Buff to Crystal Finish", "instruction": "Immediately buff away residue with a clean, dry, plush microfiber towel. Keep dry for 2 hours for initial cure."}]'), ('488afce5-2a82-492b-8ad9-4838940a438e', 'da1c2345-2c3f-48a3-bba8-5c31a55178c7', 'Air Freshener', 'air-freshener', 'air-freshener', 'Long lasting fragrance that leaves your car smelling fresh. Choose from various scents.', null, '30.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:31.098487+00', '{"Base": "Fine Fragrance Oil & Pure Distilled Water", "Safety": "Non-Staining on Fabric & Carpets", "Volume": "100ml / 250ml / 5L Options", "Longevity": "Long-Lasting Odor Neutralizing Formula", "Available Scents": "Sea Breeze, Cherry / Lavender, Summer Radiance"}', '["Premium Non-Masking Odor Encapsulation Technology", "Eliminates Smoke, Pet & Food Odors at the Source", "Refined Luxury Cologne Scents That Never Overwhelm", "Safe to Mist onto Floor Mats, Fabric Seats & Boot Liners"]', '[{"title": "Clean Cabin", "instruction": "Vacuum interior carpets and wipe down dusty surfaces for best scent retention."}, {"title": "Mist Footwells", "instruction": "Spray 3-4 pumps into front and rear footwell carpets and under seats."}, {"title": "Recirculate AC", "instruction": "Turn on vehicle AC on recirculation mode for 2 minutes to distribute aroma evenly."}, {"title": "Enjoy Fragrance", "instruction": "Re-apply weekly or as needed to maintain a fresh showroom aroma."}]'), ('4a9f258e-dad7-441c-999f-24a15b33c096', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Snow Foam', 'snow-foam', 'snow-foam', 'Thick, clinging pre‑wash foam that breaks down dirt and grime before contact washing.', null, '50.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:07.936434+00', '{"Type": "Heavy Pre-Wash Dirt Loosening Snow Foam", "pH Level": "7.5 Safe Neutral", "Fragrance": "Sweet Candy Apple", "Dwell Time": "Up to 10 Minutes Hanging Foam", "Foam Lance Dilution": "1:5 to 1:10 Ratio with Warm Water"}', '["Creates a Thick Blanket of Foam That Clings to Vertical Panels", "Softens and Encapsulates Road Filth Before You Touch the Paint", "Greatly Reduces Risk of Swirl Marks and Wash Scratches", "Completely Safe for Waxes, Sealants, PPF & Ceramic Coatings"]', '[{"title": "Fill Lance Bottle", "instruction": "Mix 100ml of Snow Foam with 900ml of warm water in your foam cannon bottle."}, {"title": "Adjust Spray Pattern", "instruction": "Set lance nozzle to wide fan and adjust top dial for thickest foam density."}, {"title": "Cover Vehicle", "instruction": "Foam entire vehicle thoroughly from bottom to top for maximum dwell coverage."}, {"title": "Pressure Rinse Off", "instruction": "Wait 5-8 minutes, then pressure rinse from top to bottom before contact wash."}]'), ('4cd7e3fd-6f13-4ece-b227-e63c8247f4cf', 'da1c2345-2c3f-48a3-bba8-5c31a55178c7', 'Interior Cleaner', 'interior-cleaner', 'interior-cleaner', 'A gentle cleaner for dashboards, plastics, and vinyl. Removes dirt without leaving residue.', null, '50.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:53.819078+00', '{"Scent": "Crisp Clean Linen", "Residue": "100% Zero Sticky Residue", "Safe On": "Dashboard, Door Panels, Leather, Vinyl, Fabrics", "pH Level": "8.5 Balanced Safe Alkaline", "Active Agents": "Bio-Enzymatic Dirt Dissolvers"}', '["Multi-Surface Cleaner Lifts Ground-In Dirt, Body Oils & Stains", "Safe for Sensitive Touchscreens & Modern Piano Black Trim", "Natural Matte Finish Keeps Interiors Looking Factory Fresh", "Anti-Bacterial Agents Leave Cabin Sanitized & Clean"]', '[{"title": "Vacuum First", "instruction": "Vacuum loose dust and grit from seats, carpets, and console areas."}, {"title": "Spray on Towel / Brush", "instruction": "Spray directly onto a microfiber cloth or soft detailing brush for precise control."}, {"title": "Agitate Gently", "instruction": "Gently agitate dirty areas, cup holders, and textured vinyl surfaces."}, {"title": "Wipe with Dry Cloth", "instruction": "Wipe away lifted grime with a clean, dry microfiber towel."}]'), ('4d37cee2-be88-4664-b4c5-2484f94a2019', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Spray Wax', 'spray-wax', 'spray-wax', 'A quick application carnauba wax that adds depth and shine while providing protection.', 'Detail Corner Spray Wax combines premium Brazilian T1 carnauba wax with reactive gloss-enhancing polymers to deliver a rich, wet-look showroom shine in minutes. The quick-misting formula melts effortlessly into paint surfaces, enhancing color depth and warmth while depositing a durable hydrophobic shield that repels water and prevents dust accumulation. Safe on all glossy paints, vinyl wraps, and paint protection films (PPF).', '85.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:08.764477+00', '{"Safe On": "Paint, Glass, Chrome, Wraps", "Durability": "4-6 Weeks", "Application": "Spray & Buff", "Formulation": "Carnauba & Polymer Emulsion"}', '["Instant Deep Wet-Look Gloss", "Hydrophobic Water-Beading Shield", "UV Inhibitors Prevent Sun Degradation", "Safe on Ceramic Coatings & Paint Protection Film"]', '[{"title": "Shake Well", "instruction": "Shake bottle thoroughly. Work on a clean, dry, and cool vehicle in the shade."}, {"title": "Mist Section", "instruction": "Mist a light, even coat directly onto a single body panel or onto a clean microfiber towel."}, {"title": "Spread & Level", "instruction": "Gently spread the product using a plush microfiber cloth to ensure complete coverage."}, {"title": "Buff to High Gloss", "instruction": "Flip to a clean, dry side of the microfiber towel and buff lightly to reveal a streak-free, mirror-like gloss."}]'), ('60cce150-9a98-4c77-be1e-6962002a3445', '933d2b3c-962e-41ad-bf18-912fe2fe6761', 'Microfibre Dryingtowel', 'microfibre-dryingtowel', 'microfibre-dryingtowel', 'Extra large plush microfibre drying towel that absorbs water instantly without scratching.', null, '75.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:55.831235+00', '{"GSM": "700 GSM Heavyweight Twisted Loop", "Size": "60cm x 90cm Jumbo Extra Large", "Color": "Stealth Grey / Red Border", "Absorption": "Holds Over 3.5 Litres of Water", "Edge Construction": "Soft Hidden-Stitch Silk Edge"}', '["Dries an Entire Full-Size SUV in a Single Pass", "Twisted-Loop Technology Glides Without Paint Drag", "Completely Scratch-Free & Streak-Free Finish", "Eliminates Water Spotting on Hot Summer Days"]', '[{"title": "Spread Across Panel", "instruction": "Lay the drying towel flat across the hood or roof of the freshly rinsed vehicle."}, {"title": "Pull by Corners", "instruction": "Gently draw the towel toward you by the two top corners without applying downward pressure."}, {"title": "Pat Lower Panels", "instruction": "Pat or wipe vertical body sides to absorb remaining water droplets."}, {"title": "Air Dry", "instruction": "Hang in a dust-free environment to air dry after use."}]'), ('63c850a9-d578-49e4-953d-085e4f044606', '933d2b3c-962e-41ad-bf18-912fe2fe6761', 'Wash Sponge', 'wash-sponge', 'wash-sponge', 'High density foam wash sponge that holds plenty of soap and glides safely over paint.', null, '25.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:11.050598+00', '{"Size": "22cm x 11cm x 7cm Ergonomic Block", "Safe On": "Clear Coats, Single Stage Paints, Wraps", "Material": "Cross-Cut Honeycomb High-Density Foam", "Absorption": "Holds Over 1 Litre of Soapy Water", "Channel Design": "8-Way Dirt Trapping Channels"}', '["Honeycomb Laser Cuts Pull Dirt Away from Paint Surface", "Extreme Soap Retention Delivers Maximum Lubrication", "Ergonomic Shape Fits Comfortably in Hand to Reduce Fatigue", "Durable Commercial Grade Foam Resists Tearing"]', '[{"title": "Submerge in Suds", "instruction": "Immerse sponge in your wash bucket and squeeze several times to saturate."}, {"title": "Glide Over Paint", "instruction": "Glide across vehicle panels in straight lines with gentle, zero-pressure strokes."}, {"title": "Rinse Frequently", "instruction": "Rinse thoroughly in a grit-guard rinse bucket after every 2-3 panels."}, {"title": "Clean & Store", "instruction": "Rinse with clean water, squeeze out excess, and air dry in a shaded area."}]'), ('6b4906c9-9f5e-412b-acf5-c3a845ffb0fd', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Clear Tyre Shine', 'clear-tyre-shine', 'clear-tyre-shine', 'A clear, silicone‑free tyre gel that gives a deep wet look. Long‑lasting and water‑resistant.', null, '85.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:35.31316+00', '{"Base": "Silicone-Free Solvent Gel", "Finish": "High Gloss Wet Look", "Durability": "3-4 Weeks Weather Resistant", "Protection": "UV Barrier Shield", "Sling Resistance": "100% Zero-Sling Formula"}', '["Ultra-High Wet Gloss Finish", "Advanced Zero-Sling Quick-Bond Chemistry", "Prevents Browning, Cracking & Dry Rot", "Silicone-Free & Body Shop Safe"]', '[{"title": "Deep Clean Tyres", "instruction": "Thoroughly scrub tyre sidewalls with Wheel & Tyre Cleaner to strip old dressings and allow dry time."}, {"title": "Apply to Pad", "instruction": "Dispense a line of Clear Tyre Shine gel directly onto a contoured foam tyre applicator."}, {"title": "Work Into Grooves", "instruction": "Smooth the gel evenly into tyre treads and sidewall lettering with overlapping strokes."}, {"title": "Cure Time", "instruction": "Allow 10-15 minutes to dry before driving. Apply a second coat for maximum wet-look gloss."}]'), ('6f7c1623-03a1-4651-a9dc-188e6d59e7de', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Wheel Tyre Cleaner', 'wheel-tyre-cleaner', 'wheel-tyre-cleaner', 'Powerful formula that dissolves brake dust, road grime, and grease. Safe for all wheel types.', null, '45.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:12.251883+00', '{"Action": "Foams on Contact & Loosens Browning", "Formula": "2-in-1 Dual Action Degreaser & Brake Dust Dissolver", "Safe On": "Painted, Polished, Powder-Coated & Chrome Alloys", "Dilution": "Ready-to-Use High Strength", "pH Level": "Non-Acidic Alkaline 10.0"}', '["Dissolves Stubborn Brake Dust & Brown Tyre Oxidation Together", "Non-Acidic Chemistry Protects Expensive Brake Calipers & Lug Nuts", "Foaming Spray Head Clings to Vertical Wheel Spokes", "Prepares Tyre Sidewalls for Maximum Dressing Adhesion"]', '[{"title": "Cool Wheels First", "instruction": "Ensure wheels and brakes are completely cold before starting."}, {"title": "Spray Rim & Rubber", "instruction": "Liberally coat both the wheel faces, barrel, and tyre sidewall."}, {"title": "Agitate with Brushes", "instruction": "Scrub tyre with a stiff tyre brush and wheel spokes with a soft detail brush."}, {"title": "High-Pressure Blast", "instruction": "Rinse completely with strong water pressure until all brown foam is gone."}]'), ('75faf376-5f36-4f10-aabf-9217c614008f', '933d2b3c-962e-41ad-bf18-912fe2fe6761', 'Clay Bar', 'clay-bar', 'clay-bar', 'Removes bonded contaminants and overspray, leaving paint glass smooth before waxing.', null, '100.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:34.921795+00', '{"Box": "Reusable Airtight Plastic Storage Case", "Grade": "Fine / Medium Detailing Grade Clay", "Weight": "100g Contaminant-Safe Bar", "Reusability": "Up to 10-15 Vehicles per Bar", "Target Contaminants": "Tree Sap, Overspray, Industrial Fallout, Rail Dust"}', '["Pulls Bonded Contaminants Off Clear Coat for Glass-Smooth Paint", "Essential Preparation Step Before Waxing, Polishing or Ceramic Coating", "Safe on Paint, Chrome, Glass & Clear Optical Plastics", "Prevents Scratches by Removing Above-Surface Grit Before Buffing"]', '[{"title": "Knead into Disc", "instruction": "Break off a third of the clay bar and flatten it into a palm-sized disc."}, {"title": "Lubricate Panel Generously", "instruction": "Spray Quick Detailer or clay lubricant liberally across a 2x2 ft section."}, {"title": "Glide with Light Pressure", "instruction": "Glide the clay disc in back-and-forth lines until the surface feels glass-smooth."}, {"title": "Fold & Knead", "instruction": "Fold the clay to expose a clean face before moving to the next section."}]'), ('8131c8f7-2266-4f24-a208-82a113fd8a8b', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Milky Tyre Shine', 'milky-tyre-shine', 'milky-tyre-shine', 'A water‑based coating that leaves tyres with a rich shine. Protects against UV and cracking.', null, '55.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:56.224315+00', '{"Finish": "Factory Satin / Natural Dark Black", "Dilutable": "Ready-to-Use", "Base Formula": "Water-Based Emulsion with Nano-Polymers", "UV Protection": "SPF 45 UV Blocking Absorbers", "Dust Attraction": "Zero Static Attraction"}', '["Restores Natural Factory OEM Satin Tyre Look", "Non-Sticky Water-Based Formula That Will Not Sling", "Moisturizes Rubber to Prevent Sidewall Cracking & Browning", "Safe for Plastic Bumper Trim, Wheel Arch Liners & Engine Bay"]', '[{"title": "Clean Tyre", "instruction": "Scrub tyre thoroughly with Wheel & Tyre Cleaner to remove road oils."}, {"title": "Apply to Sponge", "instruction": "Dispense 2-3 coin-sized drops onto a contoured tyre applicator sponge."}, {"title": "Work Across Sidewall", "instruction": "Smooth the lotion evenly along the tyre curve, working into lettering."}, {"title": "Dry & Matte Finish", "instruction": "Dries completely within 5 minutes to a deep, non-greasy satin sheen."}]'), ('82ebd687-7a09-48ef-9722-caa406e0c1c0', '1088d521-6527-40c5-a7bc-d5cb529a00e6', 'Window Cleaner', 'window-cleaner', 'window-cleaner', 'A streak free formula that cuts through grime, road film, and fingerprints.', 'Detail Corner Window Cleaner is an advanced ammonia-free glass cleaning formulation engineered to cut through stubborn road film, bug splatters, vinyl off-gassing haze, and oily fingerprints without streaking. Specially balanced for automotive use, it is 100% safe for tinted windows, optical gauge clusters, navigation screens, and sensitive heads-up displays, leaving glass crystal clear for maximum driving safety.', '30.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:21:30.239194+00', '{"Base": "Ammonia-Free Alcohol Solvent Blend", "Scent": "Fresh Mountain Air", "Clarity": "Optically Clear Streak-Free Formula", "Anti-Fog": "Mild Anti-Fog Hydrophobic A