apanese Paints"]', '[{"title": "Decontaminate Paint", "instruction": "Wash and clay the vehicle to remove all bonded above-surface contaminants."}, {"title": "Pad Preparation", "instruction": "Apply 3-4 pea-sized drops of Crystal Gloss to a soft foam finishing pad."}, {"title": "Work Panel", "instruction": "Polish in a 2x2 ft crosshatch pattern at medium speed until polish turns translucent."}, {"title": "Wipe & Inspect", "instruction": "Wipe clean with a 450 GSM edgeless microfiber towel under inspection lighting."}]'), ('bd25211a-6d0c-4e7c-b262-fae70e2e9854', 'fa9ff472-05db-48eb-80d7-936803d5ceb3', 'Iron Remover', 'iron-remover', 'iron-remover', 'Changes colour on contact with iron particles, safely lifting them from paint, wheels, and glass.', null, '130.00', null, true, false, 0, 5, '2026-08-10 09:53:31.745609+00', '2026-10-29 19:20:54.612691+00', '{"Odor": "Cherry Masked Fragrance", "pH Level": "6.8 pH Balanced (Acid-Free)", "Safe Surfaces": "Alloy Wheels, Clear Coat, Chrome, Glass", "Active Ingredient": "Sodium Thioglycolate Complex", "Reaction Indicator": "Color Changing (Clear to Deep Purple)"}', '["Chemically Neutralizes Embedded Sintered Iron & Brake Dust", "Visible Color Changing Reaction Proves Contaminant Removal", "Prevents Paint Pitting & Sub-Surface Rust Spots", "Acid-Free Formula Safe on All Factory OEM & Aftermarket Rims"]', '[{"title": "Ensure Cool Surface", "instruction": "Never apply in direct sunlight or on warm wheels/paintwork."}, {"title": "Spray Evenly", "instruction": "Spray liberal mist across wheels and lower vehicle body panels."}, {"title": "Observe Reaction", "instruction": "Wait 3-5 minutes as the liquid turns intensely purple, dissolving iron particles."}, {"title": "Agitate & Rinse", "instruction": "Agitate stubborn areas with a detail brush and pressure rinse completely."}]'), ('c5ac5848-9562-41b0-a9cf-31c9ac0ce088', '933d2b3c-962e-41ad-bf18-912fe2fe6761', 'Detail Brushes', 'detail-brushes', 'detail-brushes', 'Soft, precision brus